/**
 * UniFFI-exported App Store Versions capability handle. A thin, binding-friendly
 * wrapper around a boxed [`AppStoreVersionsImpl`]; async work runs on the tokio
 * runtime. Reached via [`crate::service::provider::Provider::app_store_versions`].
 */
public protocol AppStoreVersionsProtocol: AnyObject, Sendable {
    
    /**
     * Cancels the active submission for `app_id`.
     *
     * Looks up the first submission in the `WAITING_FOR_REVIEW` or `IN_REVIEW`
     * state for `app_id` and marks it canceled. When no such submission exists
     * this is a no-op that returns `Ok(())`.
     *
     * # Errors
     * [`StackError::PendingAgreements`] on a pending-agreements 403,
     * [`StackError::Http`] on any other non-2xx response, [`StackError::Decode`]
     * on malformed JSON, or [`StackError::Network`] on transport failure.
     */
    func cancelReview(appId: String) async throws 
    
    /**
     * Cancels the active submission for `app_id`, removing a not-yet-approved
     * submission from review.
     *
     * Fetches the app's active/cancellable submissions and clears them: an
     * in-flight submission (`WAITING_FOR_REVIEW` / `IN_REVIEW` /
     * `UNRESOLVED_ISSUES`) is canceled, and a not-yet-submitted submission
     * (`READY_FOR_REVIEW`) has its items removed. Either path returns the
     * `appStoreVersion` to `PREPARE_FOR_SUBMISSION`. When there is no active
     * submission this is a no-op that returns `Ok(())`.
     *
     * # Errors
     * [`StackError::PendingAgreements`] on a pending-agreements 403,
     * [`StackError::Http`] on any other non-2xx response, [`StackError::Decode`]
     * on malformed JSON, or [`StackError::Network`] on transport failure.
     */
    func cancelSubmission(appId: String) async throws 
    
    /**
     * Creates a phased (staged) release for `version_id` with the initial
     * `state`, returning the created phased release. `state` is the raw ASC
     * `phasedReleaseState` value (`INACTIVE` / `ACTIVE` / `PAUSED` /
     * `COMPLETE`).
     *
     * # Errors
     * [`StackError::PendingAgreements`] on a pending-agreements 403,
     * [`StackError::Http`] on any other non-2xx response, [`StackError::Decode`]
     * on malformed JSON, or [`StackError::Network`] on transport failure.
     */
    func createPhasedRelease(versionId: String, state: String) async throws  -> PhasedReleaseInfo
    
    /**
     * Creates a new (empty) screenshot set of `display_type` in the version
     * localization identified by `localization_id`, returning the created set.
     *
     * `display_type` is the raw ASC `screenshotDisplayType` value (e.g.
     * `APP_IPHONE_67`), passed through verbatim. The returned set has an empty
     * `screenshots` list — a freshly created set has none until screenshots are
     * uploaded into it.
     *
     * # Errors
     * [`StackError::PendingAgreements`] on a pending-agreements 403,
     * [`StackError::Http`] on any other non-2xx response, [`StackError::Decode`]
     * on malformed JSON, or [`StackError::Network`] on transport failure.
     */
    func createScreenshotSet(localizationId: String, displayType: String) async throws  -> ScreenshotSetInfo
    
    /**
     * Creates a new App Store version for `app_id` on `platform` with
     * `version_string`, returning the created version. `platform` is the raw ASC
     * value (`IOS` / `MAC_OS` / `TV_OS` / `VISION_OS`).
     *
     * # Errors
     * [`StackError::Http`] on a non-2xx response, [`StackError::Decode`] on
     * malformed JSON, or [`StackError::Network`] on transport failure.
     */
    func createVersion(appId: String, platform: String, versionString: String) async throws  -> AppStoreVersionInfo
    
    /**
     * Deletes the phased release identified by `id`.
     *
     * # Errors
     * [`StackError::PendingAgreements`] on a pending-agreements 403,
     * [`StackError::Http`] on any other non-2xx response, or
     * [`StackError::Network`] on transport failure.
     */
    func deletePhasedRelease(id: String) async throws 
    
    /**
     * Deletes the screenshot identified by `screenshot_id`.
     *
     * # Errors
     * [`StackError::PendingAgreements`] on a pending-agreements 403,
     * [`StackError::Http`] on any other non-2xx response, or
     * [`StackError::Network`] on transport failure.
     */
    func deleteScreenshot(screenshotId: String) async throws 
    
    /**
     * Deletes the screenshot set identified by `screenshot_set_id`.
     *
     * # Errors
     * [`StackError::PendingAgreements`] on a pending-agreements 403,
     * [`StackError::Http`] on any other non-2xx response, or
     * [`StackError::Network`] on transport failure.
     */
    func deleteScreenshotSet(screenshotSetId: String) async throws 
    
    /**
     * Deletes the version identified by `id`.
     *
     * # Errors
     * [`StackError::Http`] on a non-2xx response or [`StackError::Network`] on
     * transport failure.
     */
