        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AppleSignInStep, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .needsCode(methods,phones,codeLength,delivery):
